import{_ as o,a0 as l,w as d,s as p,ao as r,I as n,x as a,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"使用 pass 密码管理器管理你的密码 | LCTT x X-CMD","titleTemplate":false,"description":"使用 pass 密码管理器管理你的密码 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 pass 密码管理器管理你的密码 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 pass 密码管理器管理你的密码 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20171121 How to organize your passwords using pass password manager","title":"使用 pass 密码管理器管理你的密码","tag":"201803","desc":""},"relativePath":"201803/20171121 How to organize your passwords using pass password manager.md","filePath":"[post].md"}'),h={name:"201803/20171121 How to organize your passwords using pass password manager.md"};function c(g,s,k,b,u,f){const e=l("Link");return d(),p("div",null,[s[13]||(s[13]=r(`<h1 id="使用-pass-密码管理器管理你的密码" tabindex="-1">使用 pass 密码管理器管理你的密码 <a class="header-anchor" href="#使用-pass-密码管理器管理你的密码" aria-label="Permalink to “使用 pass 密码管理器管理你的密码”">​</a></h1><h3 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to “目标”">​</a></h3><p>学习在 Linux 上使用 pass 密码管理器来管理你的密码</p><h3 id="条件" tabindex="-1">条件 <a class="header-anchor" href="#条件" aria-label="Permalink to “条件”">​</a></h3><ul><li>需要 root 权限来安装需要的包</li></ul><h3 id="难度" tabindex="-1">难度 <a class="header-anchor" href="#难度" aria-label="Permalink to “难度”">​</a></h3><p>简单</p><h3 id="约定" tabindex="-1">约定 <a class="header-anchor" href="#约定" aria-label="Permalink to “约定”">​</a></h3><ul><li><code>#</code> - 执行指定命令需要 root 权限，可以是直接使用 root 用户来执行或者使用 <code>sudo</code> 命令来执行</li><li><code>$</code> - 使用普通的非特权用户执行指定命令</li></ul><h3 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to “介绍”">​</a></h3><p>如果你有根据不同的意图设置不同密码的好习惯，你可能已经感受到需要一个密码管理器的必要性了。在 Linux 上有很多选择，可以是专有软件（如果你敢用的话）也可以是开源软件。如果你跟我一样喜欢简洁的话，你可能会对 <code>pass</code> 感兴趣。</p><h3 id="第一步" tabindex="-1">第一步 <a class="header-anchor" href="#第一步" aria-label="Permalink to “第一步”">​</a></h3><p>pass 作为一个密码管理器，其实际上是一些你可能早已每天使用的、可信赖且实用的工具的一种封装，比如 <code>gpg</code> 和 <code>git</code> 。虽然它也有图形界面，但它专门设计能成在命令行下工作的：因此它也可以在 headless 机器上工作（LCTT 译注：根据 wikipedia 的说法，所谓 headless 是指没有显示器、键盘和鼠标的机器，一般通过网络链接来控制）。</p><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h3><p>pass 在主流的 Linux 发行版中都是可用的，你可以通过包管理器安装：</p><h4 id="fedora" tabindex="-1">Fedora <a class="header-anchor" href="#fedora" aria-label="Permalink to “Fedora”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf install pass</span></span></code></pre></div><h4 id="rhel-和-centos" tabindex="-1">RHEL 和 CentOS <a class="header-anchor" href="#rhel-和-centos" aria-label="Permalink to “RHEL 和 CentOS”">​</a></h4><p>pass 不在官方仓库中，但你可以从 <code>epel</code> 中获取道它。要在 CentOS7 上启用后面这个源，只需要执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum install epel-release</span></span></code></pre></div><p>然而在 Red Hat 企业版的 Linux 上，这个额外的源是不可用的；你需要从 EPEL 官方网站上下载它。</p><h4 id="debian-和-ubuntu" tabindex="-1">Debian 和 Ubuntu <a class="header-anchor" href="#debian-和-ubuntu" aria-label="Permalink to “Debian 和 Ubuntu”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt-get install pass</span></span></code></pre></div><h4 id="arch-linux" tabindex="-1">Arch Linux <a class="header-anchor" href="#arch-linux" aria-label="Permalink to “Arch Linux”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pacman -S pass</span></span></code></pre></div><h3 id="初始化密码仓库" tabindex="-1">初始化密码仓库 <a class="header-anchor" href="#初始化密码仓库" aria-label="Permalink to “初始化密码仓库”">​</a></h3><p>安装好 <code>pass</code> 后，就可以开始使用和配置它了。首先，由于 <code>pass</code> 依赖于 <code>gpg</code> 来对我们的密码进行加密并以安全的方式进行存储，我们必须准备好一个 gpg 密钥对。</p><p>首先我们要初始化密码仓库：这就是一个用来存放 gpg 加密后的密码的目录。默认情况下它会在你的 <code>$HOME</code> 创建一个隐藏目录，不过你也可以通过使用 <code>PASSWORD_STORE_DIR</code> 这一环境变量来指定另一个路径。让我们运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pass init</span></span></code></pre></div><p>然后 <code>password-store</code> 目录就创建好了。现在，让我们来存储我们第一个密码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pass edit mysite</span></span></code></pre></div><p>这会打开默认文本编辑器，我么只需要输入密码就可以了。输入的内容会用 gpg 加密并存储为密码仓库目录中的 <code>mysite.gpg</code> 文件。</p><p><code>pass</code> 以目录树的形式存储加密后的文件，也就是说我们可以在逻辑上将多个文件放在子目录中以实现更好的组织形式，我们只需要在创建文件时指定存在哪个目录下就行了，像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pass edit foo/bar</span></span></code></pre></div><p>跟上面的命令一样，它也会让你输入密码，但是创建的文件是放在密码仓库目录下的 <code>foo</code> 子目录中的。要查看文件组织结构，只需要不带任何参数运行 <code>pass</code> 命令即可：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pass</span></span>
<span class="line"><span>Password Store</span></span>
<span class="line"><span>├── foo</span></span>
<span class="line"><span>│   └── bar</span></span>
<span class="line"><span>└── mysite</span></span></code></pre></div><p>若想修改密码，只需要重复创建密码的操作就行了。</p><h3 id="获取密码" tabindex="-1">获取密码 <a class="header-anchor" href="#获取密码" aria-label="Permalink to “获取密码”">​</a></h3><p>有两种方法可以获取密码：第一种会显示密码到终端上，方法是运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pass mysite</span></span></code></pre></div><p>然而更好的方法是使用 <code>-c</code> 选项让 <code>pass</code> 将密码直接拷贝到剪切板上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pass -c mysite</span></span></code></pre></div><p>这种情况下剪切板中的内容会在 <code>45</code> 秒后自动清除。两种方法都会要求你输入 gpg 密码。</p><h3 id="生成密码" tabindex="-1">生成密码 <a class="header-anchor" href="#生成密码" aria-label="Permalink to “生成密码”">​</a></h3><p><code>pass</code> 也可以为我们自动生成（并自动存储）安全密码。假设我们想要生成一个由 15 个字符组成的密码：包含字母，数字和特殊符号，其命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pass generate mysite 15</span></span></code></pre></div><p>若希望密码只包含字母和数字则可以是使用 <code>--no-symbols</code> 选项。生成的密码会显示在屏幕上。也可以通过 <code>--clip</code> 或 <code>-c</code> 选项让 <code>pass</code> 把密码直接拷贝到剪切板中。通过使用 <code>-q</code> 或 <code>--qrcode</code> 选项来生成二维码：</p><p><img src="https://linuxconfig.org/images/pass-manager-qrcode.png" alt="qrcode"></p><p>从上面的截屏中可看出，生成了一个二维码，不过由于运行该命令时 <code>mysite</code> 的密码已经存在了，<code>pass</code> 会提示我们确认是否要覆盖原密码。</p><p><code>pass</code> 使用 <code>/dev/urandom</code> 设备作为（伪）随机数据生成器来生成密码，同时它使用 <code>xclip</code> 工具来将密码拷贝到粘帖板中，而使用 <code>qrencode</code> 来将密码以二维码的形式显示出来。在我看来，这种模块化的设计正是它最大的优势：它并不重复造轮子，而只是将常用的工具包装起来完成任务。</p><p>你也可以使用 <code>pass mv</code>、<code>pass cp</code> 和 <code>pass rm</code> 来重命名、拷贝和删除密码仓库中的文件。</p><h3 id="将密码仓库变成-git-仓库" tabindex="-1">将密码仓库变成 git 仓库 <a class="header-anchor" href="#将密码仓库变成-git-仓库" aria-label="Permalink to “将密码仓库变成 git 仓库”">​</a></h3><p><code>pass</code> 另一个很棒的功能就是可以将密码仓库当成 git 仓库来用：通过版本管理系统能让我们管理密码更方便。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pass git init</span></span></code></pre></div><p>这会创建 git 仓库，并自动提交所有已存在的文件。下一步就是指定跟踪的远程仓库了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pass git remote add &lt;name&gt; &lt;url&gt;</span></span></code></pre></div><p>我们可以把这个密码仓库当成普通仓库来用。唯一的不同点在于每次我们新增或修改一个密码，<code>pass</code> 都会自动将该文件加入索引并创建一个提交。</p><p><code>pass</code> 有一个叫做 <code>qtpass</code> 的图形界面，而且也支持 Windows 和 MacOs。通过使用 <code>PassFF</code> 插件，它还能获取 firefox 中存储的密码。在它的项目网站上可以查看更多详细信息。试一下 <code>pass</code> 吧，你不会失望的！</p><hr>`,59)),n("p",null,[s[1]||(s[1]=a("via: ",-1)),i(e,{href:"https://linuxconfig.org/how-to-organize-your-passwords-using-pass-password-manager"},{default:t(()=>[...s[0]||(s[0]=[a("https://linuxconfig.org/how-to-organize-your-passwords-using-pass-password-manager",-1)])]),_:1})]),n("p",null,[s[5]||(s[5]=a("作者：",-1)),i(e,{href:"https://linuxconfig.org"},{default:t(()=>[...s[2]||(s[2]=[a("Egidio Docile",-1)])]),_:1}),s[6]||(s[6]=a(" 译者：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[7]||(s[7]=a(" 校对：",-1)),i(e,{href:"https://github.com/locez"},{default:t(()=>[...s[4]||(s[4]=[a("Locez",-1)])]),_:1})]),n("p",null,[s[10]||(s[10]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[9]||(s[9]=[a("Linux中国",-1)])]),_:1}),s[12]||(s[12]=a(" 荣誉推出",-1))])])}const C=o(h,[["render",c]]);export{y as __pageData,C as default};
